<template>
<AppLayout><main class="mx-auto max-w-7xl space-y-6"><header class="flex justify-between"><div><p class="text-sm text-primary-600">发卡运营</p><h1 class="text-2xl font-bold">发卡商城</h1></div><button class="btn btn-primary" @click="openCreate">新建商品</button></header><div class="grid gap-4 sm:grid-cols-4"><div v-for="c in cards" :key="c.label" class="card p-4"><p class="text-sm text-gray-500">{{c.label}}</p><p class="text-2xl font-semibold">{{c.value}}</p></div></div>
<div class="card"><DataTable :columns="productColumns" :data="products" :loading="loading" row-key="id"><template #cell-name="{row}"><b>{{row.name}}</b><p class="text-xs text-gray-500">{{row.description}}</p></template><template #cell-price="{value}">{{money(value)}}</template><template #cell-limit_per_user="{value}">{{value||'不限'}}</template><template #cell-status="{value}">{{value==='active'?'销售中':'已下架'}}</template><template #cell-stock="{row}">{{row.available_stock}} / {{row.sold_count}}</template><template #cell-actions="{row}"><button class="btn btn-secondary btn-sm" @click="manage(row)">管理</button><button class="ml-1 btn btn-secondary btn-sm" @click="edit(row)">编辑</button><button v-if="row.status==='disabled'" class="ml-1 btn btn-danger btn-sm" @click="deleteProduct(row)">删除</button></template></DataTable></div>
<BaseDialog :show="showForm" :title="editing?'编辑商品':'新建商品'" width="wide" @close="showForm=false"><div class="space-y-3"><label>商品名称<input v-model="form.name" class="input mt-1 w-full"/></label><label>售价<input v-model.number="form.price" type="number" min="0" step=".01" class="input mt-1 w-full"/></label><label>单用户限购次数（留空不限）<input v-model.number="form.limit_per_user" type="number" min="1" class="input mt-1 w-full"/></label><label>说明<textarea v-model="form.description" class="input mt-1 w-full"/></label><label v-if="editing">状态<select v-model="form.status" class="input mt-1 w-full"><option value="active">销售中</option><option value="disabled">已下架</option></select></label></div><template #footer><button class="btn btn-primary" @click="save">保存</button></template></BaseDialog>
<BaseDialog :show="!!selected" :title="selected?.name||''" width="extra-wide" @close="selected=null"><div class="flex justify-between border-b pb-3"><div><button class="btn btn-secondary" @click="tab='inventory'">库存</button><button class="ml-2 btn btn-secondary" @click="tab='orders'">订单</button></div><button v-if="tab==='inventory'" class="btn btn-primary" @click="showImport=true">导入兑换码</button></div><div v-if="tab==='inventory'" class="pt-4"><div class="mb-3"><button class="btn btn-danger" :disabled="!keys.length" @click="remove(keys)">删除所选 ({{keys.length}})</button><button class="ml-2 btn btn-secondary" :disabled="!keys.length" @click="changeMany('disabled')">作废所选</button><button class="ml-2 btn btn-secondary" :disabled="!keys.length" @click="changeMany('available')">设为可售</button></div><DataTable :columns="inventoryColumns" :data="inventory.items" :loading="detailLoading" row-key="id" selectable :selected-keys="keys" @update:selectedKeys="keys=$event.map(Number)"><template #cell-code="{value}"><code>{{value}}</code></template><template #cell-status="{value}">{{labelStatus(value)}}</template><template #cell-sold_at="{value}">{{time(value)}}</template><template #cell-created_at="{value}">{{time(value)}}</template><template #cell-actions="{row}"><template v-if="row.status!=='sold'"><button class="btn btn-secondary btn-sm" @click="change(row,row.status==='available'?'disabled':'available')">{{row.status==='available'?'作废':'可售'}}</button><button class="ml-1 btn btn-danger btn-sm" @click="remove([row.id])">删除</button></template><span v-else>不可变更</span></template></DataTable><Pagination v-if="inventory.total>inventory.page_size" :page="inventory.page" :page-size="inventory.page_size" :total="inventory.total" @update:page="loadInventory" @update:pageSize="size=>{invSize=size;loadInventory(1)}"/></div><div v-else class="pt-4"><DataTable :columns="orderColumns" :data="orders.items" :loading="detailLoading" row-key="id"><template #cell-price="{value}">{{money(value)}}</template><template #cell-code="{value}"><code>{{value}}</code></template><template #cell-created_at="{value}">{{time(value)}}</template></DataTable><Pagination v-if="orders.total>orders.page_size" :page="orders.page" :page-size="orders.page_size" :total="orders.total" @update:page="loadOrders" @update:pageSize="size=>{ordSize=size;loadOrders(1)}"/></div></BaseDialog>
<BaseDialog :show="showImport" title="导入兑换码" width="wide" @close="showImport=false"><p class="text-sm text-gray-500">每行一条兑换码，重复值会跳过。</p><textarea v-model="codes" class="input mt-3 min-h-56 w-full font-mono" placeholder="CODE-001&#10;CODE-002"/><template #footer><button class="btn btn-secondary" @click="showImport=false">取消</button><button class="btn btn-primary" @click="importCodes">确认导入</button></template></BaseDialog></main></AppLayout>
</template>
<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';import AppLayout from '@/components/layout/AppLayout.vue';import BaseDialog from '@/components/common/BaseDialog.vue';import DataTable from '@/components/common/DataTable.vue';import Pagination from '@/components/common/Pagination.vue';import type{Column}from '@/components/common/types';import{adminShopAPI,type ShopAdminOrder,type ShopInventoryCode,type ShopOverview}from '@/api/admin/shop';import type{ShopPage,ShopProduct}from '@/api/shop';import{useAppStore}from '@/stores/app';import{formatDateTimeStandard}from '@/utils/format'
const app=useAppStore(),products=ref<ShopProduct[]>([]),overview=ref<ShopOverview>({product_count:0,active_products:0,available_stock:0,sold_count:0,revenue:0}),loading=ref(false),showForm=ref(false),showImport=ref(false),editing=ref<ShopProduct|null>(null),selected=ref<ShopProduct|null>(null),tab=ref<'inventory'|'orders'>('inventory'),detailLoading=ref(false),keys=ref<number[]>([]),codes=ref(''),invSize=ref(20),ordSize=ref(20),inventory=ref<ShopPage<ShopInventoryCode>>({items:[],total:0,page:1,page_size:20,pages:1}),orders=ref<ShopPage<ShopAdminOrder>>({items:[],total:0,page:1,page_size:20,pages:1}),form=reactive({name:'',description:'',price:0,status:'active',limit_per_user:null as number|null})
const productColumns:Column[]=[{key:'name',label:'商品'},{key:'price',label:'售价'},{key:'limit_per_user',label:'限购'},{key:'status',label:'状态'},{key:'stock',label:'库存 / 已售'},{key:'actions',label:'操作'}],inventoryColumns:Column[]=[{key:'code',label:'兑换码'},{key:'status',label:'状态'},{key:'buyer',label:'购买用户'},{key:'sold_at',label:'售出时间'},{key:'created_at',label:'导入时间'},{key:'actions',label:'操作'}],orderColumns:Column[]=[{key:'order_no',label:'订单号'},{key:'buyer',label:'购买用户'},{key:'price',label:'成交价'},{key:'code',label:'兑换码'},{key:'created_at',label:'购买时间'}],cards=computed(()=>[{label:'商品',value:overview.value.product_count},{label:'可售库存',value:overview.value.available_stock},{label:'已售',value:overview.value.sold_count},{label:'销售额',value:money(overview.value.revenue)}]),money=(v:number)=>`¥${Number(v||0).toFixed(2)}`,labelStatus=(v:string)=>v==='available'?'可售':v==='sold'?'已售':'已作废',time=(v:string|null|undefined)=>formatDateTimeStandard(v)||'-'
async function load(){loading.value=true;try{[products.value,overview.value]=await Promise.all([adminShopAPI.listProducts(),adminShopAPI.getOverview()])}finally{loading.value=false}}function openCreate(){editing.value=null;Object.assign(form,{name:'',description:'',price:0,status:'active',limit_per_user:null});showForm.value=true}function edit(p:ShopProduct){editing.value=p;Object.assign(form,{...p,limit_per_user:p.limit_per_user??null});showForm.value=true}async function save(){if(editing.value)await adminShopAPI.updateProduct(editing.value.id,form);else await adminShopAPI.createProduct(form);showForm.value=false;load()}async function manage(p:ShopProduct){selected.value=p;keys.value=[];await Promise.all([loadInventory(1),loadOrders(1)])}async function loadInventory(page:number){if(!selected.value)return;detailLoading.value=true;try{inventory.value=await adminShopAPI.listInventory(selected.value.id,{page,page_size:invSize.value})}finally{detailLoading.value=false}}async function loadOrders(page:number){if(!selected.value)return;detailLoading.value=true;try{orders.value=await adminShopAPI.listOrders(selected.value.id,{page,page_size:ordSize.value})}finally{detailLoading.value=false}}async function change(i:ShopInventoryCode,status:'available'|'disabled'){if(selected.value){await adminShopAPI.updateInventoryStatus(selected.value.id,i.id,status);loadInventory(inventory.value.page)}}async function changeMany(status:'available'|'disabled'){if(selected.value){await Promise.all(keys.value.map(id=>adminShopAPI.updateInventoryStatus(selected.value!.id,id,status)));keys.value=[];loadInventory(inventory.value.page)}}async function remove(ids:number[]){if(selected.value){await adminShopAPI.deleteInventory(selected.value.id,ids);keys.value=[];loadInventory(inventory.value.page);load()}}async function importCodes(){if(selected.value&&codes.value.trim()){const r=await adminShopAPI.addCodes(selected.value.id,codes.value);codes.value='';showImport.value=false;app.showSuccess(`已导入 ${r.added} 条兑换码`);loadInventory(1);load()}}async function deleteProduct(p:ShopProduct){if(confirm(`删除“${p.name}”？`)){await adminShopAPI.deleteProduct(p.id);load()}}onMounted(load)
</script>
